import {
  getServerApiCandidates,
  isRetryableApiResponseStatus,
} from '@/lib/api-config';

const CLIENT_PROXY_RETRY_DELAYS_MS = [250, 500] as const;

function isSafeRetryMethod(init?: RequestInit) {
  const method = init?.method?.toUpperCase() ?? 'GET';
  return method === 'GET' || method === 'HEAD';
}

function wait(ms: number) {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

async function fetchViaBrowserProxy(path: string, init?: RequestInit) {
  const shouldRetry = isSafeRetryMethod(init);
  const totalAttempts = shouldRetry
    ? CLIENT_PROXY_RETRY_DELAYS_MS.length + 1
    : 1;

  for (let attempt = 0; attempt < totalAttempts; attempt += 1) {
    try {
      const response = await fetch(`/api/proxy${path}`, init);

      if (
        !shouldRetry ||
        !isRetryableApiResponseStatus(response.status) ||
        attempt === totalAttempts - 1
      ) {
        return response;
      }

      await response.body?.cancel().catch(() => undefined);
    } catch (error) {
      if (
        error instanceof Error &&
        (error.name === 'AbortError' || !shouldRetry || attempt === totalAttempts - 1)
      ) {
        throw error;
      }

      if (!(error instanceof Error) && (!shouldRetry || attempt === totalAttempts - 1)) {
        throw error;
      }
    }

    const retryDelayMs = CLIENT_PROXY_RETRY_DELAYS_MS[attempt];
    if (retryDelayMs) {
      await wait(retryDelayMs);
    }
  }

  throw new Error(`Failed to fetch ${path} through the browser API proxy.`);
}

export async function apiFetch(path: string, init?: RequestInit) {
  if (typeof window !== 'undefined') {
    return fetchViaBrowserProxy(path, init);
  }

  let lastError: unknown;
  const attemptedUrls: string[] = [];

  for (const baseUrl of getServerApiCandidates()) {
    const url = `${baseUrl}${path}`;
    attemptedUrls.push(url);
    try {
      const response = await fetch(url, init);

      if (isRetryableApiResponseStatus(response.status)) {
        await response.body?.cancel().catch(() => undefined);
        lastError = new Error(
          `API candidate ${url} returned transient status ${response.status}`,
        );
        continue;
      }

      // If we got a response, it means we reached A server.
      // We should return it and let the caller handle it (even if not ok).
      // Retrying other ports only makes sense if the fetch ITSELF failed (network error).
      return response;
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        throw error;
      }

      // Fetch only throws on network errors (e.g. connection refused).
      // In this case, we continue to the next candidate.
      lastError = error;
    }
  }

  // If we reach here, it means NO candidate was reachable (all threw network errors).
  const detail =
    lastError instanceof Error ? lastError.message : 'Sin detalle adicional';

  throw new Error(
    `No fue posible conectar con la API. URLs probadas: ${attemptedUrls.join(', ')}. Detalle: ${detail}`,
  );
}
